import test from 'node:test';
import assert from 'node:assert/strict';
import Module, { createRequire } from 'node:module';
import fs from 'node:fs';
import path from 'node:path';

/**
 * Characterization test for services/node-agent/src/exposure.js + docker.js.
 *
 * tests/fixtures/dockerExposureGolden.json was generated by running the ORIGINAL (pre-refactor) docker.js through a
 * fake Docker over a matrix of inputs. Every pre-existing mode must still produce byte-identical container config;
 * only `raw_tcp` and `internal_only` (both broken before) are allowed to differ, and their new behaviour is asserted
 * explicitly below.
 */

const require_ = createRequire(import.meta.url);
const golden: Record<string, { Labels: Record<string, string>; PortBindings: Record<string, unknown>; NetworkMode: string }> = JSON.parse(
  fs.readFileSync(path.resolve('tests/fixtures/dockerExposureGolden.json'), 'utf8')
);

const created: any[] = [];
const FakeDocker = function () {
  return {
    getContainer: () => ({ remove: async () => { const e: any = new Error('not found'); e.statusCode = 404; throw e; } }),
    createContainer: async (cfg: any) => { created.push(cfg); return { start: async () => {}, inspect: async () => ({ Id: 'cid' }) }; },
  };
};
const M: any = Module;
const realLoad = M._load;
M._load = function (request: string, ...rest: unknown[]) {
  return request === 'dockerode' ? FakeDocker : realLoad.call(this, request, ...rest);
};
const dockerFile = path.resolve('services/node-agent/src/docker.js');
delete require_.cache[dockerFile];
const { runContainer } = require_(dockerFile);
M._load = realLoad;

async function build(k: { exposureMode: string | null; routingMode: string; frameworkPreset: string; publishedPort: number | null; subdomain: string | null; internalPort: number }) {
  created.length = 0;
  await runContainer({
    deploymentId: 'cdep0000000001', imageTag: 'img:1', internalPort: k.internalPort, subdomain: k.subdomain ?? undefined,
    rootDomain: 'example.com', deploymentsRootDomain: 'apps.example.com', routingMode: k.routingMode,
    ...(k.exposureMode === null ? {} : { exposureMode: k.exposureMode }), frameworkPreset: k.frameworkPreset, publishedPort: k.publishedPort,
  });
  const c = created[0];
  return { Labels: c.Labels, PortBindings: c.HostConfig.PortBindings, NetworkMode: c.HostConfig.NetworkMode };
}

const keys = Object.keys(golden).map((s) => ({ raw: s, k: JSON.parse(s) }));

test('exposure: pre-existing modes are unchanged (characterization vs original docker.js)', async () => {
  const existing = keys.filter(({ k }) => k.exposureMode === null || ['ssl_with_proxy', 'ssl_direct', 'no_ssl'].includes(k.exposureMode));
  assert.ok(existing.length >= 96, `expected the full matrix, got ${existing.length}`);
  for (const { raw, k } of existing) {
    assert.deepEqual(await build(k), golden[raw], `behaviour changed for ${raw}`);
  }
});

test('exposure: raw_tcp (what the API/dashboard call "direct") now binds a host port exactly like no_ssl', async () => {
  const rawKeys = keys.filter(({ k }) => k.exposureMode === 'raw_tcp');
  assert.ok(rawKeys.length >= 32);
  for (const { k } of rawKeys) {
    const asNoSsl = { ...k, exposureMode: 'no_ssl' };
    assert.deepEqual(await build(k), await build(asNoSsl), JSON.stringify(k));
  }
  const withPort = await build({ exposureMode: 'raw_tcp', routingMode: 'proxied', frameworkPreset: 'auto', publishedPort: 25565, subdomain: 'myapp', internalPort: 3000 });
  assert.deepEqual(withPort.PortBindings, { '3000/tcp': [{ HostPort: '25565' }], '3000/udp': [{ HostPort: '25565' }] });
  assert.ok(!('traefik.enable' in withPort.Labels), 'no public HTTP router for a direct-port deployment');
  // Record of the old behaviour this replaces:
  assert.deepEqual(golden[JSON.stringify({ exposureMode: 'raw_tcp', routingMode: 'proxied', frameworkPreset: 'auto', publishedPort: 25565, subdomain: 'myapp', internalPort: 3000 })].PortBindings, {}, 'original bound nothing');
});

test('exposure: internal_only has no Traefik router and no host port, in every combination', async () => {
  const internal = keys.filter(({ k }) => k.exposureMode === 'internal_only');
  assert.ok(internal.length >= 32);
  for (const { k, raw } of internal) {
    const c = await build(k);
    assert.deepEqual(c.PortBindings, {}, raw);
    assert.equal(Object.keys(c.Labels).filter((l) => l.startsWith('traefik')).length, 0, `no Traefik labels: ${raw}`);
    assert.equal(c.NetworkMode, 'bridge', 'does not join the public proxy network');
  }
  // Record of the old behaviour this replaces (web service got a public router):
  const old = golden[JSON.stringify({ exposureMode: 'internal_only', routingMode: 'proxied', frameworkPreset: 'auto', publishedPort: null, subdomain: 'myapp', internalPort: 3000 })];
  assert.equal(old.Labels['traefik.enable'], 'true', 'original exposed internal_only containers through Traefik');
});

test('exposure: invalid ports fail early with a clear message instead of an opaque Docker error', async () => {
  const base = { exposureMode: 'no_ssl', routingMode: 'proxied', frameworkPreset: 'auto', subdomain: null, internalPort: 3000 };
  // (0 / NaN are falsy and mean "not set": the host port falls back to the internal port, as it always has.)
  for (const bad of [70000, -1, 1.5, 'abc']) {
    await assert.rejects(build({ ...base, publishedPort: bad as never }), /Invalid published port/, String(bad));
  }
  const unset = await build({ ...base, publishedPort: 0 as never });
  assert.deepEqual(unset.PortBindings, { '3000/tcp': [{ HostPort: '3000' }], '3000/udp': [{ HostPort: '3000' }] });
  await assert.doesNotReject(build({ ...base, publishedPort: 65535 }));
  await assert.doesNotReject(build({ ...base, publishedPort: 1 }));
});
